package com.motionstudio.part3
data class Clip(val id:String,var start:Double,var duration:Double,val source:String?=null){init{require(id.isNotBlank()&&start>=0&&duration>=0)}}
data class Marker(val time:Double,val name:String)
class TimelineEnginePro{val tracks=mutableListOf<MutableList<Clip>>();val markers=mutableListOf<Marker>();var playhead=0.0;fun addTrack()=tracks.add(mutableListOf());fun addClip(track:Int,c:Clip){require(track in tracks.indices);tracks[track].add(c);tracks[track].sortBy{it.start}};fun trim(track:Int,id:String,newStart:Double,newDuration:Double){val c=find(track,id);require(newStart>=0&&newDuration>=0);c.start=newStart;c.duration=newDuration};fun split(track:Int,id:String,time:Double){val c=find(track,id);require(time>c.start&&time<c.start+c.duration);val right=Clip(c.id+"#2",time,c.start+c.duration-time,c.source);c.duration=time-c.start;tracks[track].add(right);tracks[track].sortBy{it.start}};fun move(track:Int,id:String,start:Double,snap:Double?=null){val c=find(track,id);c.start=(snap?.let{(start/it).toInt()*it}?:start).coerceAtLeast(0.0);tracks[track].sortBy{it.start}};fun duplicate(track:Int,id:String):Clip{val c=find(track,id);val n=c.copy(id=c.id+"#copy",start=c.start);tracks[track].add(n);return n};fun delete(track:Int,id:String){tracks[track].removeIf{it.id==id}};fun rippleDelete(track:Int,id:String){val c=find(track,id);val end=c.start+c.duration;tracks[track].remove(c);tracks[track].filter{it.start>=end}.forEach{it.start-=c.duration}};fun group(ids:Set<String>):List<Clip> =tracks.flatten().filter{it.id in ids};fun addMarker(m:Marker){require(m.time>=0);markers.add(m);markers.sortBy{it.time}};private fun find(t:Int,id:String)=tracks[t].first{it.id==id}}
